/** CLI-only one-time panel credential encryption. Backup DB first. */
declare(strict_types=1);if(PHP_SAPI!=='cli'){http_response_code(404);exit;}require_once dirname(__DIR__).'/config.php';$key=rx_secret_master_key();if($key===null){fwrite(STDERR,"Set REDFOX_MASTER_KEY first. Generate: openssl rand -hex 32\n");exit(2);}$dry=in_array('--dry-run',$argv,true);$fields=['password_panel','api_key','xui_api_token','secret_code'];$rows=$pdo->query('SELECT id,'.implode(',',$fields).' FROM marzban_panel')->fetchAll(PDO::FETCH_ASSOC);$changed=0;foreach($rows as $r){$sets=[];$params=[];foreach($fields as $f){$v=(string)($r[$f]??'');if($v!==''&&!rx_secret_is_encrypted($v)){$sets[]="`$f`=?";$params[]=rx_secret_encrypt($v);}}if(!$sets)continue;$changed++;echo($dry?'PLAN ':'ENCRYPT ').'panel id '.$r['id'].' fields='.count($sets)."\n";if(!$dry){$params[]=$r['id'];$q=$pdo->prepare('UPDATE marzban_panel SET '.implode(',',$sets).' WHERE id=?');$q->execute($params);}}echo"Rows changed: $changed\n";
